import{_ as t,o as a,c as s,a0 as o}from"./chunks/framework.CnTYizyl.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/configuration.md","filePath":"guide/deployment/configuration.md"}'),r={name:"guide/deployment/configuration.md"};function i(n,e,d,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>All Hub services are configured via environment variables, managed by <code>envix</code> through each service&#39;s <code>ConfigModule</code>.</p><h2 id="common-variables" tabindex="-1">Common Variables <a class="header-anchor" href="#common-variables" aria-label="Permalink to &quot;Common Variables&quot;">​</a></h2><p>These variables are shared across all services:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>No</td><td>HTTP server port (default varies by service)</td></tr><tr><td><code>AUTHUP_URL</code></td><td>Yes</td><td>Authup identity provider URL</td></tr><tr><td><code>REDIS_URL</code></td><td>No</td><td>Redis connection URL (for pub/sub and caching)</td></tr><tr><td><code>AMQP_URL</code></td><td>No</td><td>RabbitMQ connection URL</td></tr><tr><td><code>COOKIE_PREFIX</code></td><td>No</td><td>Namespace prefixed onto the <code>access_token</code> cookie the authup middleware falls back to when a request carries no <code>Authorization</code> header (e.g. a bucket/file stream download). See <a href="#frontend-variables-client-ui">Frontend Variables</a> — must match client-ui&#39;s <code>COOKIE_PREFIX</code>.</td></tr></tbody></table><h2 id="message-delivery-rabbitmq" tabindex="-1">Message delivery (RabbitMQ) <a class="header-anchor" href="#message-delivery-rabbitmq" aria-label="Permalink to &quot;Message delivery (RabbitMQ)&quot;">​</a></h2><p>When <code>AMQP_URL</code> is set, commands to the worker, storage and telemetry services (build, distribute, bucket create, …) travel over durable RabbitMQ queues.</p><ul><li><strong>A failed or interrupted command is retried, up to 5 attempts.</strong> A handler error, or a redelivery after a consumer died mid-command (crash, lost connection, consumer timeout), re-publishes the command with exponential backoff (1s, 2s, 4s, 8s). An exhausted command is dropped with an error log line naming its type and id. Before this, a redelivered command was dropped silently after its first attempt.</li><li><strong>Set RabbitMQ&#39;s <code>consumer_timeout</code> above your longest analysis or master-image build.</strong> A command is acknowledged only once its handler finishes. If a build outlasts the timeout (RabbitMQ default: 30 minutes), the broker closes the channel and redelivers the command. A replica still running it ignores the copy, but a redelivery that lands on another worker replica starts a second build.</li><li>Worker outcome events (started, progress, finished, failed) are applied one at a time per server-core replica, and a late <code>started</code>/<code>progress</code> event no longer moves a finished or failed process back to <code>started</code>.</li><li>Failure events carry the error&#39;s <code>name</code>, <code>message</code> and <code>code</code> instead of <code>{}</code>.</li></ul><h2 id="authup-upgrade-to-beta-68" tabindex="-1">Authup upgrade to beta.68 <a class="header-anchor" href="#authup-upgrade-to-beta-68" aria-label="Permalink to &quot;Authup upgrade to beta.68&quot;">​</a></h2><p>Upgrade the Authup server and all Hub services together. Hub now requires Authup <code>1.0.0-beta.68</code> and reads <code>GET /authorization</code> using the service&#39;s own <code>CLIENT_ID</code> / <code>CLIENT_SECRET</code> credentials. Grant that client <code>permission_read</code> with <code>realmScope: &quot;ownOrNull&quot;</code> for a single realm, or <code>&quot;any&quot;</code> when serving multiple realms. The default <code>&quot;own&quot;</code> grant cannot read global policy definitions. The built-in <code>system</code> client already has the required access.</p><p>Each authenticated HTTP request and socket connection fetches one catalog and combines it with the caller&#39;s introspected grants. All permission checks within that request/connection reuse the local evaluator. Catalog errors fail the request; there is no fallback to permission names. Catalogs are not cached across requests. Existing token-introspection caching and socket-session lifetimes still apply, so changes to grants are visible when those are refreshed.</p><p>This preserves policy trees and grant realm scopes at the evaluator boundary. Existing endpoints that only perform a permission pre-check still perform a pre-check: this upgrade does not add row-policy checks or collection filtering to those endpoints. Restricting every entity read/write by resource attributes is a separate service-level change.</p><p>The frontend kit uses a single <code>POST /authorization/check</code> batch for UI gates and refreshes it at the policy expiry returned by Authup. Hub navigation follows those refreshes. Browser users do not need <code>permission_read</code> merely to render menus.</p><p>Authup&#39;s beta.67 upgrade also applies its folders/event-aggregate migration and pins database timestamps to UTC. Follow the <a href="https://github.com/authup/authup/releases/tag/v1.0.0-beta.67" target="_blank" rel="noreferrer">Authup upgrade notes</a> for existing databases that used local time. Beta.68 quotes newly serialized strings; Hub&#39;s text transformer reads both these and legacy unquoted messenger payloads, so no Hub data migration is needed.</p><h2 id="authup-upgrade-to-beta-69" tabindex="-1">Authup upgrade to beta.69 <a class="header-anchor" href="#authup-upgrade-to-beta-69" aria-label="Permalink to &quot;Authup upgrade to beta.69&quot;">​</a></h2><p>Hub now requires Authup <code>1.0.0-beta.69</code>, a security release. Read the <a href="https://authup.org/guide/deployment/upgrading#security-hardening-that-changes-behaviour" target="_blank" rel="noreferrer">Authup upgrade guide</a> before upgrading. Hub needs no code or data changes; these points concern the Authup deployment Hub runs against:</p><ul><li><strong>Tokens are bound to their realm.</strong> On a Redis-backed Authup, drop the <code>oauth2_token_claims*</code> keys once after upgrading, or tokens verified before the upgrade keep bypassing the new check until they expire.</li><li><strong>Client reads are realm-gated.</strong> Hub&#39;s service client creates and reads the per-node and per-analysis Authup clients in the realm of that node or analysis. A Hub client whose <code>client_*</code> grants are <code>own</code> or <code>ownOrNull</code> no longer sees clients in other realms; grant <code>any</code> (the built-in <code>system</code> client already has it).</li><li><strong>HTTP Basic names resolve in the route realm or the master realm.</strong> Hub&#39;s Harbor webhook authenticates with the registry client&#39;s <strong>id</strong>, which resolves globally, so it is unaffected.</li><li><strong>Rate limiting is two-stage.</strong> Behind one NAT address (a clinic or office network) raise <code>rateLimitAnonymousMax</code>, and pin Authup&#39;s <code>trustProxy</code> to the hop count of your proxy.</li><li><strong>Some users sign in once more.</strong> Token cookies are now written <code>SameSite=Lax</code>, and <code>Secure</code> on https. Behind a TLS-terminating proxy, forward <code>X-Forwarded-Proto</code> (the <a href="./reverse-proxy.html">reverse proxy</a> example already does) so server-side cookie writes in client-ui get <code>Secure</code> too.</li></ul><h2 id="database-variables" tabindex="-1">Database Variables <a class="header-anchor" href="#database-variables" aria-label="Permalink to &quot;Database Variables&quot;">​</a></h2><p>Used by <code>server-core</code>, <code>server-storage</code>, <code>server-telemetry</code>, and <code>server-messenger</code>:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_TYPE</code></td><td>Yes</td><td><code>mysql</code>, <code>postgres</code>, or <code>better-sqlite3</code></td></tr><tr><td><code>DB_HOST</code></td><td>Yes*</td><td>Database hostname</td></tr><tr><td><code>DB_PORT</code></td><td>Yes*</td><td>Database port</td></tr><tr><td><code>DB_USERNAME</code></td><td>Yes*</td><td>Database username</td></tr><tr><td><code>DB_PASSWORD</code></td><td>Yes*</td><td>Database password</td></tr><tr><td><code>DB_DATABASE</code></td><td>Yes</td><td>Database name (or <code>:memory:</code> for SQLite)</td></tr></tbody></table><p>*Not required for SQLite.</p><h3 id="sqlite-has-no-upgrade-path" tabindex="-1">SQLite has no upgrade path <a class="header-anchor" href="#sqlite-has-no-upgrade-path" aria-label="Permalink to &quot;SQLite has no upgrade path&quot;">​</a></h3><p>Migrations only run for <code>mysql</code> and <code>postgres</code>. On SQLite the schema is built from the entity classes by <code>synchronize()</code>, and only when no schema exists yet — so an <strong>existing</strong> SQLite database is never migrated or altered on upgrade.</p><p>Schema changes therefore break a persistent SQLite deployment. The rename of the <code>analysis</code> table to <code>analyses</code> is one such change: a SQLite database created before it keeps the old table, and queries against the new name fail.</p><p>Use SQLite only for tests and throwaway/in-memory (<code>:memory:</code>) instances. For any database you intend to keep, use MySQL or PostgreSQL. To carry an existing SQLite database across a schema change, export its data and re-import it into a freshly created database.</p><h3 id="timestamps-are-stamped-and-read-in-utc" tabindex="-1">Timestamps are stamped and read in UTC <a class="header-anchor" href="#timestamps-are-stamped-and-read-in-utc" aria-label="Permalink to &quot;Timestamps are stamped and read in UTC&quot;">​</a></h3><p>On MySQL and PostgreSQL every Hub service pins its database sessions to UTC (<code>time_zone</code> on MySQL, <code>TimeZone</code> on PostgreSQL), reads the zone-less <code>created_at</code> / <code>updated_at</code> columns back as UTC, and binds <code>Date</code> parameters in UTC — whatever timezone the database server or the host running Hub is set to. The same pin applies to the <code>migration</code> CLI. There is nothing to configure, and <code>DB_PIN_TIMEZONE</code> is not needed. A database and host already running in UTC (the container image sets no <code>TZ</code>) see no change.</p><p>Before, the database stamped these columns in its session timezone, the driver read them in the process timezone, and the messenger&#39;s expiry sweep compared its <code>expires_at</code> column against a <code>Date</code> bound in the process timezone, so the three only agreed when every clock ran in UTC.</p><p><strong>If the database itself ran in local time</strong>, rows it stamped before this upgrade hold local wall-clock values and now read as UTC, shifted by that offset. Rows written afterwards are correct. Check the database&#39;s zone before upgrading:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- PostgreSQL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW timezone;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- MySQL</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @@</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">time_zone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, @@system_time_zone;</span></span></code></pre></div><p>If it is not UTC and the historical values matter, convert them <strong>while no Hub service is writing</strong>: stop every replica of the old version, run the conversion, then start the new version. Do not convert after the new version has started, or during a rolling upgrade where old and new replicas write side by side: the statements cannot tell a legacy local-time row from a correct UTC one, so they would shift the correct rows too. Convert each table and column once, with the zone the database used:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- PostgreSQL</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> events </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ZONE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Europe/Berlin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ZONE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;UTC&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- MySQL (needs the server&#39;s time zone tables loaded)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> events </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CONVERT_TZ(created_at, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Europe/Berlin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;+00:00&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>A database setting that contradicts the pin stops the boot with an error naming it: a MySQL <code>timezone</code> other than UTC, a MySQL <code>dateStrings</code> or <code>typeCast</code>, or a PostgreSQL <code>TimeZone</code> other than UTC in the driver&#39;s startup <code>options</code> (e.g. via <code>DB_DRIVER_EXTRA</code>). Remove it — half a pin would shift values instead of fixing them. A MySQL replication setup is refused the same way for now, since its per-connection session cannot be pinned yet.</p><h3 id="replicas-and-boot-time-migrations" tabindex="-1">Replicas and boot-time migrations <a class="header-anchor" href="#replicas-and-boot-time-migrations" aria-label="Permalink to &quot;Replicas and boot-time migrations&quot;">​</a></h3><p>Each service applies pending migrations when it starts. On MySQL and PostgreSQL it now does so while holding a database lock named after the service (<code>server-core:migration</code>, <code>server-storage:migration</code>, …), so replicas that start at the same time apply the chain once: one runs it, the others wait and then find nothing pending. The <code>migration run</code> / <code>migration revert</code> CLI commands take the same lock, so a migration job and a booting replica cannot overlap either. server-core&#39;s Harbor registry setup (<code>HARBOR_URL</code>) is serialized the same way.</p><p>A replica that cannot get the lock within 60 seconds fails its boot instead of migrating unlocked; the orchestrator restarts it, and by then the chain has been applied. Each lock holds one pooled connection while the migration runs on another, so the connection pool needs at least two connections.</p><h2 id="storage-variables-server-storage" tabindex="-1">Storage Variables (server-storage) <a class="header-anchor" href="#storage-variables-server-storage" aria-label="Permalink to &quot;Storage Variables (server-storage)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>MINIO_ENDPOINT</code></td><td>Yes</td><td>MinIO/S3 endpoint URL</td></tr><tr><td><code>MINIO_ACCESS_KEY</code></td><td>Yes</td><td>S3 access key</td></tr><tr><td><code>MINIO_SECRET_KEY</code></td><td>Yes</td><td>S3 secret key</td></tr><tr><td><code>MINIO_USE_SSL</code></td><td>No</td><td>Enable SSL for MinIO connection</td></tr><tr><td><code>MINIO_PORT</code></td><td>No</td><td>MinIO port</td></tr></tbody></table><h2 id="telemetry-variables-server-telemetry" tabindex="-1">Telemetry Variables (server-telemetry) <a class="header-anchor" href="#telemetry-variables-server-telemetry" aria-label="Permalink to &quot;Telemetry Variables (server-telemetry)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>VICTORIA_LOGS_URL</code></td><td>Yes</td><td>VictoriaLogs endpoint URL</td></tr><tr><td><code>EVENT_RETENTION_DAYS</code></td><td>No</td><td>Days an audit/event row is kept before the daily sweep removes it (default <code>7</code>; <code>0</code> = keep forever)</td></tr></tbody></table><h2 id="frontend-variables-client-ui" tabindex="-1">Frontend Variables (client-ui) <a class="header-anchor" href="#frontend-variables-client-ui" aria-label="Permalink to &quot;Frontend Variables (client-ui)&quot;">​</a></h2><p>The full list lives in the <a href="./../../reference/frontend/#environment-variables">frontend reference</a>. Two of them are deployment decisions rather than service addresses, and go together:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>NUXT_PUBLIC_COOKIE_DOMAIN</code></td><td>No</td><td><code>Domain</code> attribute for the UI&#39;s session cookies. <strong>Leave empty.</strong></td></tr><tr><td><code>NUXT_PUBLIC_AUTHUP_COOKIE_PREFIX</code></td><td>No</td><td>Namespace prefixed onto every session cookie name. Set this <strong>whenever <code>NUXT_PUBLIC_COOKIE_DOMAIN</code> is widened</strong>, so Authup&#39;s own hosted pages can&#39;t collide with the UI&#39;s cookies on that domain.</td></tr></tbody></table><p>Setting a prefix is only safe once the backend agrees on it: <code>server-core</code>, <code>server-storage</code>, <code>server-telemetry</code> and <code>server-messenger</code> each fall back to reading the <code>access_token</code> cookie (for requests that can&#39;t carry an <code>Authorization</code> header — a stream download is a top-level navigation) when the identity middleware finds nothing else. That fallback needs the <strong>same</strong> prefix, via each service&#39;s own <code>COOKIE_PREFIX</code> env var (see <a href="#common-variables">Common Variables</a>) — set it to the exact same value as <code>NUXT_PUBLIC_AUTHUP_COOKIE_PREFIX</code> / <code>COOKIE_PREFIX</code>, verbatim (no separator is inserted automatically on either side).</p><h3 id="where-authup-is-served-matters" tabindex="-1">Where Authup is served matters <a class="header-anchor" href="#where-authup-is-served-matters" aria-label="Permalink to &quot;Where Authup is served matters&quot;">​</a></h3><p>The UI and Authup&#39;s own hosted pages persist their sessions under the <strong>same cookie names</strong>. If both can see each other&#39;s cookies, they hydrate, rotate and revoke each other&#39;s tokens, and the user is logged out on the next page reload.</p><p>Empty (host-only) cookies are correct in every layout. Setting a <code>Domain</code> delivers the cookies to every subdomain of that value — including Authup&#39;s host, if it sits below it — in which case also set <code>NUXT_PUBLIC_AUTHUP_COOKIE_PREFIX</code> to keep the two cookie sets apart. Serving Authup on a path of the UI&#39;s own origin no longer needs either variable as of Authup <code>1.0.0-beta.64</code> (<a href="https://github.com/authup/authup/issues/3495" target="_blank" rel="noreferrer">authup#3495</a>): the consoles scope their own cookies to that sub-path automatically.</p><p>The layout matrix and the upgrade caveat are documented under <a href="./../../reference/frontend/#session-cookies">Session cookies</a>.</p>`,48)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
